static int square(p2d89_q14 x,p2d89_q14 y,const P2D89_Provider *p){p2d89_q14 q[]={-1536,-1536,1536,-1536,1536,1536,-1536,1536};unsigned int i;for(i=0U;i<4U;++i){q[i*2U]=(p2d89_q14)(q[i*2U]+x);q[i*2U+1U]=(p2d89_q14)(q[i*2U+1U]+y);}return p2d89_i_poly(q,4U,1,p);}
static int handle(P2D89_ShapeId id,const P2D89_Provider *p){p2d89_q14 x,y;x=0;y=0;if(id==P2D89_SHAPE_RESIZE_N)y=-14336;else if(id==P2D89_SHAPE_RESIZE_S)y=14336;else if(id==P2D89_SHAPE_RESIZE_E)x=14336;else if(id==P2D89_SHAPE_RESIZE_W)x=-14336;else if(id==P2D89_SHAPE_RESIZE_NE){x=14336;y=-14336;}else if(id==P2D89_SHAPE_RESIZE_NW){x=-14336;y=-14336;}else if(id==P2D89_SHAPE_RESIZE_SE){x=14336;y=14336;}else if(id==P2D89_SHAPE_RESIZE_SW){x=-14336;y=14336;}else return 0;return square(x,y,p);}
static int emit(P2D89_ShapeId id,const P2D89_Provider *p){static const p2d89_q14 box[]={-12288,-12288,12288,-12288,12288,12288,-12288,12288};static const p2d89_q14 pts[]={-12288,-12288,0,-12288,12288,-12288,12288,0,12288,12288,0,12288,-12288,12288,-12288,0};unsigned int i;if(id==P2D89_SHAPE_SELECTION_BOX)return p2d89_i_poly(box,4U,1,p);if(id==P2D89_SHAPE_SELECTION_BOX_8_HANDLES){if(!p2d89_i_poly(box,4U,1,p))return 0;for(i=0U;i<8U;++i)if(!square(pts[i*2U],pts[i*2U+1U],p))return 0;return 1;}return handle(id,p);}
const P2D89_Submodule p2d89_submodule_gizmos_selection={{P2D89_MODULE_GIZMOS,"gizmos","selection",(unsigned int)(sizeof(shapes)/sizeof(shapes[0]))},shapes,emit};
